import pytest

from src.calc import add, div, mul


def test_add():
    assert add(2, 3) == 5


def test_add_with_zero_and_negative_number():
    assert add(0, -4) == -4


def test_mul():
    assert mul(2, 3) == 6


def test_div():
    assert div(6, 3) == 2


def test_div_non_exact_values():
    assert div(5, 2) == 2.5


def test_div_with_negative_values():
    assert div(-6, 3) == -2


def test_div_by_zero():
    with pytest.raises(ValueError):
        div(1, 0)
